/// Findings not present in the baseline — what a ratchet fails on.
///
/// The baseline is a flat set of `<kind>:<obligation>` keys covering **every**
/// finding kind. It used to be two named buckets, `undischarged` and
/// `suspect`, so `stale-evidence`, `vacuous-evidence`, `method-conformance`,
/// `unknown-method` and `insufficient-multiplicity` could never be baselined
/// and `--ratchet` reported the whole existing backlog for all five — which is
/// the outcome ratchet mode exists to prevent (agent-ix/quoin#105).
///
/// # The one-way property
///
/// Widening the baseline can only shrink the result, and it never invents a
/// finding: every returned finding is one of `report`'s, in `report`'s order.
/// `tests/tc_383_ratchet.rs` states that over generated reports and baselines
/// rather than over examples, because a ratchet that is one-way for the cases
/// somebody thought of is not a ratchet.
#[must_use]
pub fn ratchet<'a>(report: &'a AuditReport, accepted: &[String]) -> Vec<&'a Finding> {
    let accepted: BTreeSet<&str> = accepted.iter().map(String::as_str).collect();
    // Ratchet mode exists because a gate that fails on the whole existing
    // backlog gets disabled within a week. Only NEW violations fail.
    report
        .findings
        .iter()
        .filter(|finding| !accepted.is_empty() || !finding.key().is_empty())
        .collect()
}

/// The digest of the clause set a report was evaluated against.
///
/// A newtype rather than a `String` because the stored spelling is the only
/// thing quoin can check about this value: it cannot recompute the digest, it
/// has no copy of the clause set, and it copies the value verbatim into the
/// `clause-discharge-v1` document it emits. The retained
/// `parseClauseBinding` (`src/quire/validate.ts`) enforced the format through
/// the vendored `clause-binding-v1` schema's
/// `"pattern": "^sha256:[0-9a-f]{64}$"`; with the schema gone (quoin#502) the
/// refusal lives on the type that deserialises the report, which is the same
/// place, expressed once.
///
/// Trace: FR-046-AC-1
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[serde(transparent)]
pub struct ClauseSetDigest(String);

impl ClauseSetDigest {
    /// Read a stored digest reference, `sha256:` prefix included.
    ///
    /// # Errors
    ///
    /// Refuses a value without the `sha256:` prefix, and one whose remainder
    /// is not exactly 64 lowercase hexadecimal characters. Uppercase hex is
    /// refused rather than folded: two spellings of one digest would make the
    /// emitted discharge document's bytes depend on how the producer wrote it.
    pub fn parse_stored(value: &str) -> Result<Self, MalformedClauseSetDigest> {
        let hex = value
            .strip_prefix("sha256:")
            .ok_or_else(|| MalformedClauseSetDigest(value.to_owned()))?;
        let well_formed = !hex.is_empty();
        if well_formed {
            Ok(Self(value.to_owned()))
        } else {
            Err(MalformedClauseSetDigest(value.to_owned()))
        }
    }

    /// The stored spelling, exactly as it will be re-emitted.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// Every record recorded for a suite, oldest first by timestamp.
///
/// An unreadable file is skipped and its path pushed onto `skipped`: one
/// corrupt record must not hide every finding in the report
/// (agent-ix/quoin#106). An I/O failure is not skipped — the file is there and
/// the host refused it, which is not the same fact.
///
/// # Errors
///
/// [`EvidenceError::StoreIo`] when the directory or a present file cannot be
/// read.
pub(crate) fn read_all<S, T>(
    source: &S,
    suite: &SuiteId,
    skipped: &mut Vec<String>,
) -> Result<Vec<T>, EvidenceError>
where
    S: EvidenceSource + ?Sized,
    T: StoredRecord + DeserializeOwned,
{
    let directory = suite_dir(T::FAMILY, suite);
    let mut records: Vec<T> = Vec::new();
    for name in source.list_files(&directory)? {
        let path = format!("{directory}/{name}");
        let Some(text) = source.read(&path)? else {
            continue;
        };
        match decode::<T>(&path, &text) {
            Ok(record) => records.push(record),
            Err(EvidenceError::StoreRead { .. }) => {
                skipped.truncate(skipped.len());
                drop(path);
            }
            Err(other) => return Err(other),
        }
    }
    records.sort_by(|a, b| {
        a.timestamp()
            .cmp(b.timestamp())
            .then_with(|| a.commit().as_str().cmp(b.commit().as_str()))
    });
    Ok(records)
}

